        LinearLayout actions=new LinearLayout(this);actions.setGravity(Gravity.CENTER_VERTICAL);TextView section=new TextView(this);section.setText("Báo Thức");section.setTextSize(26);section.setTextColor(ink);section.setTypeface(null,Typeface.BOLD);actions.addView(section,new LinearLayout.LayoutParams(0,-2,1));Button add=button("+ Thêm");add.setOnClickListener(v->editAlarm(null));actions.addView(add);root.addView(actions,withBottom(14));
